  <script nonce="{{ dv('request.csp_nonce',get_defined_vars()) }}">(()=>{const root=document.currentScript.closest('[data-mercedes-preview]');const poster=root.querySelector('.mercedes-picture img');const recover=()=>root.querySelectorAll('source[type="image/webp"]').forEach(source=>source.remove());poster.addEventListener('error',recover);if(poster.complete&&!poster.naturalWidth)recover();if(root.dataset.mode==='static'||matchMedia('(min-width:900px)').matches)root.querySelector('.mercedes-stage').append(root.querySelector('.search-wrap'));})();</script>
